package in.kabadiwala.connect.model; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.*; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant; @Document("refresh_tokens") public class RefreshToken {@Id public String id; @Indexed public String userId; @Indexed(unique=true) public String tokenHash; public Instant expiresAt; public boolean revoked; public String replacedByHash; public Instant createdAt=Instant.now();}